package br.com.tapeteskalke.repository; import br.com.tapeteskalke.entity.Compra; import java.math.BigDecimal; import java.time.LocalDate; import java.util.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; public interface CompraRepository extends JpaRepository<Compra,String> { @EntityGraph(attributePaths={"fornecedor","itens","itens.produto"}) @Query("select c from Compra c where c.id=:id") Optional<Compra> detail(@Param("id")String id); @Query("select coalesce(sum(c.totalCusto),0) from Compra c where c.status='FINALIZADA' and c.dataCompra between :from and :to") BigDecimal totalFinalized(@Param("from")LocalDate from,@Param("to")LocalDate to); @Query("select c from Compra c left join fetch c.fornecedor order by c.dataCompra desc, c.createdAt desc") List<Compra> listWithSupplier(); }
